import{_ as t,o,c as r,ag as n}from"./chunks/framework.2cFhd8Ux.js";const h=JSON.parse('{"title":"Course B (\\"Engineering Software with AI\\"): the $0 tool landscape, checked 2 November 2026","description":"","frontmatter":{"source":"research/notes/tools-senior.md"},"headers":[],"relativePath":"research/notes/tools-senior.md","filePath":"research/notes/tools-senior.md"}'),a={name:"research/notes/tools-senior.md"};function s(i,e,d,l,c,g){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="course-b-engineering-software-with-ai-the-0-tool-landscape-checked-2-november-2026" tabindex="-1">Course B (&quot;Engineering Software with AI&quot;): the $0 tool landscape, checked 2 November 2026 <a class="header-anchor" href="#course-b-engineering-software-with-ai-the-0-tool-landscape-checked-2-november-2026" aria-label="Permalink to &quot;Course B (&quot;Engineering Software with AI&quot;): the $0 tool landscape, checked 2 November 2026&quot;">​</a></h1><p><strong>Scope.</strong> These notes cover only what is <strong>new or different</strong> from Course A&#39;s handout (<code>TOOLS.md</code>, verified 2026-10-21) and its notes (<code>research/notes/2026-10/tool-changes-since-september.md</code>, <code>research/notes/tools-ide-cli-apis-hosting.md</code>). Course B students are adults (CS seniors and graduate students), so 18+ rules are not a blocker. Their work is heavier, though: agent loops on large codebases, MCP servers, CI, code review and evals.</p><p><strong>Dates and labels.</strong></p><ul><li>Every fact was checked on <strong>2026-11-02</strong> unless it is tagged <strong>[A]</strong>, which means it was carried over from Course A&#39;s notes dated 2026-10-21 and was not re-checked.</li><li><strong>[official]</strong>: the vendor&#39;s own page.</li><li><strong>[3rd]</strong>: press, blogs or trackers.</li><li><strong>[snippet]</strong>: seen only in a search summary.</li><li><strong>[GH]</strong>: read from the GitHub API or the npm/PyPI registries on 2026-11-02 (UTC timestamps).</li><li><strong>UNVERIFIED</strong> marks anything that could not be confirmed.</li></ul><p><strong>The headline finding.</strong> On a $0 budget, the scarce resource is <strong>model capacity, not tools</strong>. Every harness worth teaching is free: VS Code, Copilot CLI, Gemini CLI, OpenCode, Cline, Goose, the MCP SDKs, CodeQL, Semgrep, Stryker and promptfoo. The free <em>inference</em> attached to them is small. Copilot Student is about <strong>$2/month</strong> of model usage, and a single default-effort Copilot code review averages <strong>$1.50</strong>. Groq&#39;s free tier allows 8K tokens per minute, and OpenRouter&#39;s free models allow 50 requests a day. The course design therefore has to spread work across several separate free pools, plus a local or lab-served model.</p><hr><h2 id="1-coding-agents-at-0-for-verified-university-students" tabindex="-1">1. Coding agents at $0 for verified university students <a class="header-anchor" href="#1-coding-agents-at-0-for-verified-university-students" aria-label="Permalink to &quot;1. Coding agents at $0 for verified university students&quot;">​</a></h2><h3 id="what-each-offer-gives" tabindex="-1">What each offer gives <a class="header-anchor" href="#what-each-offer-gives" aria-label="Permalink to &quot;What each offer gives&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Offer</th><th>What a student gets</th><th>Limits</th><th>Sign-up friction</th><th>Age / region</th><th>Training on data</th><th>Source</th></tr></thead><tbody><tr><td><strong>GitHub Copilot Student</strong> (via GitHub Education)</td><td>Agent mode, MCP and Copilot CLI included. &quot;Copilot in the cloud&quot; (cloud agent) and code review included. Third-party agents excluded. Unlimited completions. <strong>Auto model selection only</strong></td><td>An AI-credit &quot;allowance&quot; whose size GitHub does not publish. Third parties and student dashboards report <strong>200 credits = $2.00/month</strong>. Credits reset 00:00 UTC on the 1st and don&#39;t roll over. When they run out you&#39;re blocked unless you set a paid budget</td><td>GitHub Education verification takes days. Eligibility is re-checked monthly [3rd]. New student sign-ups were <strong>paused 20 Apr–17 Jun 2026</strong></td><td>13+, enrolled students worldwide</td><td>Individual-plan interaction data is used for training unless you opt out at github.com/settings/copilot/features [A]. No student exemption is stated</td><td><a href="https://docs.github.com/en/copilot/get-started/plans" target="_blank" rel="noreferrer">Plans</a>, <a href="https://docs.github.com/en/copilot/concepts/billing-and-usage/individuals/billing" target="_blank" rel="noreferrer">billing</a> [official]; <a href="https://www.layer3labs.io/guides/github-copilot-student" target="_blank" rel="noreferrer">Layer3Labs, upd. 2026-10-01</a> [3rd]; <a href="https://github.com/orgs/community/discussions/197557" target="_blank" rel="noreferrer">community #197557</a></td></tr><tr><td><strong>GitHub Pro via Education</strong></td><td>Codespaces 180 h/month and 20 GB storage. &quot;3K Actions minutes&quot;. Packages 2 GB. Pages from private repos</td><td>Codespaces hours are core-weighted: 180 h ≈ <strong>90 h on a 2-core</strong> machine. Actions is now a <strong>$18/month</strong> compute entitlement ≈ 3,000 Linux minutes</td><td>Same verification as above</td><td>13+</td><td>n/a</td><td><a href="https://github.com/education/students" target="_blank" rel="noreferrer">Education</a>, <a href="https://docs.github.com/en/billing/concepts/product-billing/github-codespaces" target="_blank" rel="noreferrer">Codespaces billing</a>, <a href="https://docs.github.com/en/billing/concepts/product-billing/github-actions" target="_blank" rel="noreferrer">Actions billing</a> [official]</td></tr><tr><td><strong>Zed Student</strong> (new; not in TOOLS.md)</td><td>Zed Pro free for <strong>1 year</strong>: <strong>$10/month</strong> of hosted-model tokens plus unlimited edit predictions. Agent Panel, MCP, and external agents through ACP</td><td>Excludes Claude Fable/Opus, GPT-6 Astra and the <em>pro</em> models. Usage is capped at the $10</td><td>GitHub account older than 30 days plus a university email. Domains are checked against JetBrains&#39; university list. Downgrades to Free after 12 months</td><td><strong>18+</strong>, worldwide</td><td>Not checked this pass. Sept notes: hosted providers are barred from training [A]</td><td><a href="https://zed.dev/docs/ai/plans-and-usage" target="_blank" rel="noreferrer">Zed plans</a>, <a href="https://zed.dev/education" target="_blank" rel="noreferrer">zed.dev/education</a> [official]</td></tr><tr><td><strong>OpenAI Codex student credits</strong></td><td>$100 of credits (2,500) usable in Codex on any ChatGPT plan, including Free</td><td>One per student; credits expire 12 months after they&#39;re granted. No claim deadline was found. One community report says the flagship model is blocked on Free accounts [A]</td><td>SheerID verification with a school email</td><td>Students in the US or Canada</td><td>ChatGPT Data Controls opt-out [A]</td><td><a href="https://help.openai.com/en/articles/20001147-codex-for-university-students" target="_blank" rel="noreferrer">OpenAI Help 20001147</a> [official, snippet]; claim page chatgpt.com/codex/students returned 403. <strong>Still untested by the course</strong></td></tr><tr><td><strong>Google AI Pro, free for 12 months</strong></td><td>Higher limits in Antigravity and Jules. Gemini 4 Argon</td><td>Antigravity&#39;s Claude 5.5 is &quot;non-trial subscriptions only&quot;, and whether the student year counts as a trial is <strong>UNVERIFIED</strong></td><td>Payment method required; <strong>auto-renews at $19.99</strong></td><td>US college students, 18+. <strong>Redeem by 31 Dec 2026</strong>, so a spring-2027 cohort must claim it in December</td><td>Gemini Apps &quot;Keep Activity&quot; setting [A]</td><td><a href="https://antigravity.google/docs/models" target="_blank" rel="noreferrer">Antigravity models</a> [official]; <a href="https://discuss.ai.google.dev/t/does-the-8-99-month-student-plan-include-access-to-the-latest-claude-models-in-antigravity/186472" target="_blank" rel="noreferrer">Google AI dev forum</a> [snippet]; deadline [A]</td></tr><tr><td><strong>Antigravity Free</strong> (IDE plus <code>agy</code> CLI)</td><td>Gemini 3.8 Flash with a weekly quota. Claude Sonnet/Opus 4.6 and GPT-OSS-120b are footnoted &quot;Will be removed on November 2, 2026&quot; (today)</td><td>Numbers not published</td><td>Personal Google account</td><td>18+, approved countries [A]</td><td>Opt-out in Settings [A]</td><td><a href="https://antigravity.google/docs/models" target="_blank" rel="noreferrer">Antigravity models</a> [official]. Whether the removal actually happened is <strong>not yet confirmed</strong></td></tr><tr><td><strong>Jules</strong> (Google&#39;s asynchronous cloud agent)</td><td><strong>15 tasks per rolling 24 h, 3 concurrent</strong>, on GitHub repos</td><td>The free-tier model is listed as &quot;Gemini 2.5 Pro&quot;, which may be stale</td><td>Google account; paid plans need @gmail.com</td><td>18+</td><td>Does &quot;not train on private repository content&quot; [A]</td><td><a href="https://jules.google/docs/usage-limits" target="_blank" rel="noreferrer">Jules usage limits</a> [official]</td></tr><tr><td><strong>Gemini CLI with a free AI Studio key</strong></td><td>Open-source CLI (Apache-2.0, v0.66.0, 27 Oct 2026 [GH])</td><td><strong>250 requests/user/day, Flash model only</strong>. Free Google-login access ended 18 Jun 2026</td><td>An AI Studio API key; no card</td><td>18+ (Gemini API terms)</td><td>Free tier is &quot;used to improve our products&quot;; human reviewers may read prompts</td><td><a href="https://geminicli.com/docs/resources/quota-and-pricing" target="_blank" rel="noreferrer">Gemini CLI quota page, upd. 2026-06-18</a> [official]; <a href="https://aistudio.google.com/docs/pricing" target="_blank" rel="noreferrer">pricing</a> [official]</td></tr><tr><td><strong>Kiro</strong> (AWS)</td><td>Free: 50 credits; &quot;open weight models and Claude Sonnet 4.5&quot;. Student offer: <strong>1,000 credits/month for 1 year</strong></td><td>Student credits don&#39;t roll over and can&#39;t be topped up</td><td>SheerID; <strong>only students at listed universities</strong>. The <strong>University of Idaho is not on the list</strong> (about 170 schools)</td><td>18+</td><td>Free-tier content may be used for service improvement [3rd]</td><td><a href="https://kiro.dev/pricing" target="_blank" rel="noreferrer">kiro.dev/pricing</a>, <a href="https://kiro.dev/students/" target="_blank" rel="noreferrer">kiro.dev/students</a> [official]</td></tr></tbody></table><h3 id="offers-that-are-closed-or-give-students-nothing-extra" tabindex="-1">Offers that are closed, or give students nothing extra <a class="header-anchor" href="#offers-that-are-closed-or-give-students-nothing-extra" aria-label="Permalink to &quot;Offers that are closed, or give students nothing extra&quot;">​</a></h3><ul><li><strong>Gemini Code Assist</strong> (consumer version): ended. <ul><li>The IDE tiers for individuals stopped on 18 Jun 2026.</li><li>The free GitHub code-review app <strong>shut down on 17 Jul 2026</strong>.</li><li><a href="https://developers.google.cn/gemini-code-assist/docs/deprecations/consumer-code-review" target="_blank" rel="noreferrer">Google deprecation notice</a> [official].</li></ul></li><li><strong>Amazon Q Developer:</strong> new Free-tier accounts have been blocked since 15 May 2026; Kiro is the successor. <a href="https://aws.amazon.com/blogs/devops/amazon-q-developer-end-of-support-announcement/" target="_blank" rel="noreferrer">AWS blog</a> [official, snippet].</li><li><strong>JetBrains:</strong> the IDEs are free through the Student Pack, but AI Free gives only <strong>3 AI credits per 30 days</strong>, with no top-ups. <a href="https://www.jetbrains.com/help/ai-assistant/licensing-and-subscriptions.html" target="_blank" rel="noreferrer">JetBrains AI plans, 2026-10-14</a> [official].</li><li><strong>Cursor:</strong> no student offer (&quot;look out for promotions… this fall&quot;). <a href="https://cursor.com/students" target="_blank" rel="noreferrer">cursor.com/students</a> [official].</li><li><strong>Devin Desktop</strong> (formerly Windsurf): no student route. The official pricing page was unreachable, so this is <strong>UNVERIFIED</strong>. <a href="https://aistudentdiscount.com/windsurf-student/" target="_blank" rel="noreferrer">aistudentdiscount</a> [3rd].</li><li><strong>Anthropic:</strong><ul><li>There is <strong>no individual student offer</strong>; Claude Code is not free [A].</li><li>Claude Campus (shared API credits through campus clubs) took applications only on <strong>1–12 Sep 2026</strong>. <a href="https://aistudentdiscount.com/claude-api-student-builder/" target="_blank" rel="noreferrer">aistudentdiscount, checked 2026-10-06</a> [3rd].</li><li>A CodePath partnership gives Claude Code to CodePath students. <a href="https://www.theregister.com/2026/02/13/anthropic_claudeifies_comp_sci_courses/" target="_blank" rel="noreferrer">The Register</a> [3rd].</li></ul></li></ul><h3 id="copilot-changes-since-course-as-check-mostly-from-github-universe-28-oct-2026" tabindex="-1">Copilot changes since Course A&#39;s check (mostly from GitHub Universe, 28 Oct 2026) <a class="header-anchor" href="#copilot-changes-since-course-as-check-mostly-from-github-universe-28-oct-2026" aria-label="Permalink to &quot;Copilot changes since Course A&#39;s check (mostly from GitHub Universe, 28 Oct 2026)&quot;">​</a></h3><ul><li><strong>Copilot Fusion</strong> is now generally available on <strong>all Copilot plans</strong>. It routes each task across models at a Standard, High or Max effort level, billed &quot;at each model&#39;s standard rate&quot;. A preview can also route to a &quot;local OpenAI-compatible server&quot;. Whether local routing uses credits, and whether Fusion replaces Auto for Free and Student, is <strong>UNVERIFIED</strong>. <a href="https://github.blog/changelog/2026-10-28-route-and-orchestrate-models-with-github-copilot-fusion" target="_blank" rel="noreferrer">Fusion</a>; <a href="https://github.blog/changelog/2026-10-28-github-copilot-fusion-now-supports-selection-of-local-models" target="_blank" rel="noreferrer">local models</a>.</li><li><strong>The new &quot;Copilot in the cloud&quot; experience is &quot;available on paid Copilot plans only&quot;</strong> (from 28 Oct), and so is Agent Merge. Whether Copilot Student counts as &quot;paid&quot; is <strong>UNVERIFIED</strong>; test it in week 0. <ul><li>Cloud sandboxes draw on a shared, dollar-based compute entitlement, and <strong>sandbox billing begins in November 2026</strong>.</li><li>Sessions running on Actions have a hard <strong>59-minute</strong> limit.</li><li>Without write access a session is read-only, so students must work on <strong>their own forks</strong>.</li><li><a href="https://github.blog/changelog/2026-10-28-work-from-anywhere-with-a-new-connected-copilot-cloud-experience" target="_blank" rel="noreferrer">Cloud experience</a>; <a href="https://github.blog/changelog/2026-10-28-agent-merge-watches-and-fixes-pull-requests-in-the-cloud" target="_blank" rel="noreferrer">Agent Merge</a>; <a href="https://docs.github.com/en/copilot/concepts/agents/cloud-agent/about-cloud-agent" target="_blank" rel="noreferrer">about cloud agent</a>.</li></ul></li><li><strong>Copilot code review costs (official estimates).</strong> These exclude Actions minutes. <ul><li>Lite: about <strong>$0.25</strong> per review.</li><li>Balanced (the default): about <strong>$1.50</strong> per review, range $0.25–$5.</li><li>Max: about <strong>$10</strong> per review, Pro+ and above only.</li><li>On a roughly $2 Student allowance, <strong>one Balanced review uses about 75% of the month</strong>.</li><li>Since 1 Jun 2026, reviews on <strong>private</strong> repos also consume Actions minutes; public repos are unaffected.</li><li><a href="https://docs.github.com/en/copilot/reference/copilot-billing/models-and-pricing" target="_blank" rel="noreferrer">Models and pricing</a>; <a href="https://github.blog/changelog/2026-10-28-copilot-code-review-merge-with-confidence-with-max-and-approvals" target="_blank" rel="noreferrer">Max/approvals</a>; <a href="https://github.blog/changelog/2026-04-27-github-copilot-code-review-will-start-consuming-github-actions-minutes-on-june-1-2026/" target="_blank" rel="noreferrer">Actions-minutes change</a>.</li></ul></li><li><strong>Per-token rates</strong> (AI credits per 1M input/output tokens; 1 credit = $0.01): GPT-6 Luna 10/50, Gemini 3.8 Flash 75/375 (promotional price until 31 Dec 2026), Claude Opus 5 500/2,500. A 200K-token agent turn on a mid-tier model therefore costs 15–50 credits. <a href="https://docs.github.com/en/copilot/reference/copilot-billing/models-and-pricing" target="_blank" rel="noreferrer">Models and pricing</a>.</li><li><strong>GitHub Agentic Workflows</strong> went generally available on 28 Oct for GitHub Free, Team and Enterprise. <ul><li>Workflows are written in Markdown and compiled to Actions YAML.</li><li>Engines: Copilot (needs a Copilot plan), Claude, Codex or Gemini, each with its own secret.</li><li>Workflows are read-only by default, with <code>safe-outputs</code>.</li><li>The default <code>max-ai-credits</code> is <strong>1,000 ($10) per run</strong>, five times a Student&#39;s monthly allowance. Lower it.</li><li><a href="https://github.blog/changelog/2026-10-28-github-agentic-workflows-generally-available" target="_blank" rel="noreferrer">Changelog</a>; <a href="https://docs.github.com/en/copilot/concepts/agent-capabilities/agent-powered-workflows-and-operations/about-github-agentic-workflows" target="_blank" rel="noreferrer">docs</a>.</li></ul></li></ul><hr><h2 id="2-open-source-agents-that-run-on-free-models" tabindex="-1">2. Open-source agents that run on free models <a class="header-anchor" href="#2-open-source-agents-that-run-on-free-models" aria-label="Permalink to &quot;2. Open-source agents that run on free models&quot;">​</a></h2><h3 id="agent-harnesses-maintenance-status-all-gh" tabindex="-1">Agent harnesses: maintenance status (all [GH]) <a class="header-anchor" href="#agent-harnesses-maintenance-status-all-gh" aria-label="Permalink to &quot;Agent harnesses: maintenance status (all [GH])&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Agent</th><th>Latest release</th><th>Licence</th><th>Status / notes</th></tr></thead><tbody><tr><td><strong>OpenCode</strong> (<code>anomalyco/opencode</code>)</td><td>v1.19.5, 28 Oct 2026</td><td>MIT</td><td>Very active. Its docs now call the hosted service <strong>&quot;OpenCode Console&quot;</strong>, which was breached in Oct 2026 [A]. Keep keys in your own environment variables</td></tr><tr><td><strong>Cline</strong></td><td>v4.1.26, 26 Oct 2026</td><td>Apache-2.0</td><td>Active; VS Code, JetBrains and CLI</td></tr><tr><td><strong>Kilo Code</strong></td><td>v7.8.18, 26 Oct 2026</td><td>—</td><td>Active; &quot;Auto Free&quot; routing [A]</td></tr><tr><td><strong>Goose</strong> (now <code>aaif-goose/goose</code> under the Agentic AI Foundation)</td><td>v1.57.0, 28 Oct 2026</td><td>Apache-2.0</td><td>Active. Moved from <code>block/goose</code></td></tr><tr><td><strong>Gemini CLI</strong></td><td>v0.66.0, 27 Oct 2026</td><td>Apache-2.0</td><td>Active; the free path is an API key only</td></tr><tr><td><strong>Codex CLI</strong></td><td>rust-v0.166.0, 29 Oct 2026</td><td>Apache-2.0</td><td>Active; needs ChatGPT sign-in or an API key</td></tr><tr><td><strong>OpenHands</strong></td><td>v1.34.0, 27 Oct 2026</td><td>—</td><td>Active; self-hostable background agent (could run on the lab GPU)</td></tr><tr><td><strong>mini-swe-agent</strong></td><td>v2.4.6, 23 Jul 2026 (last push 2 Nov)</td><td>—</td><td>A roughly 100-line agent; an ideal reference for the &quot;build your own coding agent&quot; assignment</td></tr><tr><td><strong>Aider</strong></td><td>v0.86.0, <strong>9 Aug 2025</strong>; last commit 22 May 2026</td><td>—</td><td>Dormant. Don&#39;t use it (unchanged from Course A)</td></tr><tr><td><strong>Continue</strong></td><td>v2.0.0 &quot;final release&quot;, 19 Jun 2026; last commit 21 Jul 2026</td><td>Apache-2.0</td><td>README: &quot;no longer actively maintained and is read-only&quot;</td></tr></tbody></table><p>Claude Code (a free binary, v2.1.317 on npm, Node ≥22) and OpenCode can both run at $0 against <strong>local Ollama</strong>. Use <code>ollama launch claude</code> or <code>ollama launch opencode</code>, or set the environment variables yourself: <code>ANTHROPIC_BASE_URL=http://localhost:11434</code>, <code>ANTHROPIC_AUTH_TOKEN=ollama</code>. Ollama&#39;s docs say &quot;OpenCode requires a context length of 64k or higher&quot;. <a href="https://docs.ollama.com/integrations/claude-code" target="_blank" rel="noreferrer">Ollama: Claude Code</a>; <a href="https://docs.ollama.com/integrations/opencode" target="_blank" rel="noreferrer">Ollama: OpenCode</a> [official].</p><h3 id="free-api-tiers-for-agents" tabindex="-1">Free API tiers for agents <a class="header-anchor" href="#free-api-tiers-for-agents" aria-label="Permalink to &quot;Free API tiers for agents&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Provider</th><th>Free limits</th><th>Fits a coding-agent loop?</th><th>Training / retention</th><th>Source</th></tr></thead><tbody><tr><td><strong>Gemini API</strong> (AI Studio key)</td><td><strong>Not published</strong> (&quot;View your active rate limits in AI Studio&quot;). Free models include <code>gemini-3.8-flash</code>, <code>gemini-3.6-flash</code>, <code>gemini-3.5-flash-lite</code>, <code>gemini-3.1-flash-lite</code>, <code>gemini-3-flash-preview</code> and Gemma 4. <strong>Gemini 4 Argon is not free.</strong> The docs moved: <code>ai.google.dev/gemini-api/docs/pricing</code> now 301-redirects to <code>aistudio.google.com/docs/pricing</code></td><td>Yes. It is the biggest free pool with a large context (Gemini CLI: 250 requests/day)</td><td>&quot;Used to improve our products: Yes&quot;; human review; 18+</td><td><a href="https://aistudio.google.com/docs/pricing" target="_blank" rel="noreferrer">Pricing</a>, <a href="https://aistudio.google.com/docs/rate-limits" target="_blank" rel="noreferrer">rate limits</a> [official]</td></tr><tr><td><strong>Groq</strong></td><td>30 RPM, 1K RPD, <strong>8K TPM</strong>, 200K TPD for <code>openai/gpt-oss-120b</code>, <code>gpt-oss-20b</code> and <code>qwen/qwen3.8-27b</code>. On 2 Nov the page only showed these as &quot;base limits for the Developer plan&quot;; the Free-tab figures were last confirmed on 21 Oct [A]. Check <code>console.groq.com/settings/limits</code></td><td><strong>Inference:</strong> 8K tokens per minute is smaller than one turn of a typical IDE or CLI agent (system prompt plus tool schemas plus files), so expect &quot;request too large&quot; errors. Fine for a student-built minimal agent with a lean prompt</td><td>No retention by default [A]</td><td><a href="https://console.groq.com/docs/rate-limits" target="_blank" rel="noreferrer">Groq rate limits</a> [official]</td></tr><tr><td><strong>OpenRouter <code>:free</code></strong></td><td>20 RPM. <strong>50/day</strong> if under 10 credits ever purchased; <strong>1,000/day</strong> at 10 or more</td><td>50/day is about one or two agent tasks. A <strong>one-time $10 top-up</strong> (optional department money) makes it workable</td><td>Depends on the provider</td><td><a href="https://openrouter.ai/docs/api-reference/limits" target="_blank" rel="noreferrer">OpenRouter limits</a> [official]</td></tr><tr><td><strong>OpenCode Zen free models</strong></td><td>11 listed, e.g. Big Pickle, GLM-5.3-Flash Free, DeepSeek V4.1 Flash Free, Nemotron 3 Ultra Free; &quot;most are free only for a limited time&quot;. No rate limits stated</td><td>Yes (built for OpenCode)</td><td><strong>Mixed.</strong> GLM-5.3-Flash Free and DeepSeek V4.1 Flash Free: zero retention, no training. Big Pickle, MiMo, Pulse Alpha and Flint: data &quot;may be used to improve the model&quot;. Nemotron (NVIDIA): logged</td><td><a href="https://opencode.ai/docs/zen/" target="_blank" rel="noreferrer">OpenCode docs</a> [official]</td></tr><tr><td><strong>Cerebras</strong></td><td><strong>No permanent free tier</strong>: $5 of credits after adding a card, expiring after 30 days</td><td>No</td><td>—</td><td><a href="https://costbench.com/software/llm-api-providers/cerebras-inference/free-plan/" target="_blank" rel="noreferrer">CostBench</a> [3rd]</td></tr><tr><td><strong>Mistral</strong> (&quot;Experiment&quot; plan)</td><td>Free with phone verification. Limits appear only in the console; third parties report about 1 request/second. Devstral and Codestral reportedly included</td><td>Marginal</td><td>API data may be used for improvement; <strong>opt-out toggle</strong> under Admin → Privacy (help article, 3 Sep 2026)</td><td><a href="https://help.mistral.ai/en/articles/455207-can-i-opt-out-of-my-input-or-output-data-being-used-for-training" target="_blank" rel="noreferrer">Mistral help</a> [official]; limits [3rd]: <strong>UNVERIFIED</strong></td></tr><tr><td><strong>Cloudflare Workers AI</strong></td><td>10,000 Neurons/day [A]</td><td>Small</td><td>—</td><td>[A]</td></tr><tr><td><strong>Ollama Cloud</strong></td><td><strong>Changed:</strong> pricing now shows &quot;Pay as you go $0… Pay per token&quot; with no included credits (Sept notes listed a free &quot;starter amount&quot;). Pro is $20/month</td><td>Not free</td><td>&quot;Never logged or trained on&quot;</td><td><a href="https://ollama.com/pricing" target="_blank" rel="noreferrer">ollama.com/pricing</a> [official]</td></tr><tr><td><strong>GitHub Models</strong></td><td>Retired 30 Jul 2026 [A]. Any 2025 course lab that used it as a free API is broken</td><td>—</td><td>—</td><td>[A]</td></tr></tbody></table><hr><h2 id="3-local-models-for-agentic-coding" tabindex="-1">3. Local models for agentic coding <a class="header-anchor" href="#3-local-models-for-agentic-coding" aria-label="Permalink to &quot;3. Local models for agentic coding&quot;">​</a></h2><p><strong>Configuration trap (official):</strong></p><ul><li>Ollama&#39;s default context is <strong>4K when VRAM is under 24 GiB</strong>, 32K at 24–48 GiB, and 256K at 48 GiB or more.</li><li>The docs say agents and coding tools &quot;should be set to at least 64000 tokens&quot;. Set it with <code>OLLAMA_CONTEXT_LENGTH=64000 ollama serve</code>.</li><li>Without that, tool calls silently fail because the system prompt gets truncated.</li><li>Ollama is at v0.40.13 (28 Oct 2026) [GH].</li><li><a href="https://docs.ollama.com/context-length" target="_blank" rel="noreferrer">Ollama context length</a>.</li></ul><table tabindex="0"><thead><tr><th>Model (Ollama tag)</th><th>Download size</th><th>Context</th><th>Tools</th><th>Where it fits</th><th>Source</th></tr></thead><tbody><tr><td><code>gpt-oss:20b</code></td><td>14 GB (MXFP4)</td><td>128K</td><td>✓ (plus thinking)</td><td>&quot;As little as 16GB memory&quot;, but with 16 GB of system RAM and no GPU, a 64K context leaves almost no headroom. A good lab-GPU model</td><td><a href="https://ollama.com/library/gpt-oss" target="_blank" rel="noreferrer">ollama.com/library/gpt-oss</a></td></tr><tr><td><code>gemma4:e4b</code> / <code>gemma4:12b</code></td><td>6.6–9.5 GB / 7.7–8.0 GB</td><td>128K / 256K</td><td>✓ native function calling</td><td><strong>The realistic choice for 16 GB CPU-only laptops</strong>, for the build-your-own-agent and MCP labs</td><td><a href="https://ollama.com/library/gemma4" target="_blank" rel="noreferrer">ollama.com/library/gemma4</a></td></tr><tr><td><code>ornith-1.5:9b</code></td><td>6.6 GB</td><td>256K</td><td>✓</td><td>Marketed as &quot;agentic coding&quot;. Licence and maker not stated on the page, so bench it before relying on it</td><td><a href="https://ollama.com/library/ornith-1.5" target="_blank" rel="noreferrer">ollama.com/library/ornith-1.5</a></td></tr><tr><td><code>devstral-small-2:24b</code></td><td>15 GB</td><td>384K</td><td>✓</td><td>Fits a 24 GB GPU. Mistral claims 65.8% on SWE-bench Verified (vendor figure). Apache-2.0; about 10 months old</td><td><a href="https://ollama.com/library/devstral-small-2" target="_blank" rel="noreferrer">ollama.com/library/devstral-small-2</a></td></tr><tr><td><code>qwen3.8:27b</code></td><td>18 GB (q4_K_M)</td><td>256K</td><td>✓ (thinking, vision)</td><td>24 GB GPU (tight at 64K context) or a 32 GB card. Every published tag is 27B; there is no small size</td><td><a href="https://ollama.com/library/qwen3.8/tags" target="_blank" rel="noreferrer">ollama.com/library/qwen3.8/tags</a></td></tr><tr><td><code>qwen3-coder:30b</code></td><td>19 GB</td><td>256K</td><td>✓</td><td>24 GB GPU; a mixture-of-experts model, so it&#39;s fast, but the tag is about a year old</td><td><a href="https://ollama.com/library/qwen3-coder" target="_blank" rel="noreferrer">ollama.com/library/qwen3-coder</a></td></tr></tbody></table><h3 id="quality-notes-stated-plainly" tabindex="-1">Quality notes, stated plainly <a class="header-anchor" href="#quality-notes-stated-plainly" aria-label="Permalink to &quot;Quality notes, stated plainly&quot;">​</a></h3><ul><li><strong>Tool calling depends on the model&#39;s training, not its size.</strong> One test found that Qwen3.5 9B and 4B &quot;output bash commands instead of invoking&quot; OpenCode&#39;s write tool. Another guide found devstral-small-2 &quot;too small for reliable function calls in OpenCode&quot;. <a href="https://github.com/imagewize/ollama-opencode-setup" target="_blank" rel="noreferrer">imagewize/ollama-opencode-setup</a> [3rd]; <a href="https://localaimaster.com/blog/opencode-ollama-setup" target="_blank" rel="noreferrer">summary</a> [3rd].</li><li><strong>A precedent for teaching with weak local models.</strong> UMich EECS 498 AASE (Fall 2026) is <strong>$0 by design</strong>, using <code>qwen3.5:4b</code> or <code>:9b</code> with Aider. Its stated reason: &quot;A small model punishes sloppy engineering visibly; that is the point&quot;. Lab machines serve students whose laptops can&#39;t run the models. <a href="https://eecs498-aase.github.io/syllabus.html" target="_blank" rel="noreferrer">UMich syllabus</a> [A].</li><li><strong>Inference:</strong> 9–27B local models work for the student-built agent, MCP tool-call testing, evals (as cheap judges or subjects) and small fixes. They are <strong>not</strong> a substitute for frontier models when navigating large open-source codebases. <ul><li>One consumer GPU serving a whole class gives you one shared queue. Plan for team-sized batches, not 30 concurrent agent loops.</li><li>Copilot CLI can list a running Ollama&#39;s models through <code>/model</code> [A], but whether this consumes credits is UNVERIFIED.</li></ul></li></ul><hr><h2 id="4-free-infrastructure-for-the-courses-techniques" tabindex="-1">4. Free infrastructure for the course&#39;s techniques <a class="header-anchor" href="#4-free-infrastructure-for-the-courses-techniques" aria-label="Permalink to &quot;4. Free infrastructure for the course&#39;s techniques&quot;">​</a></h2><h3 id="github-changed-since-course-as-check" tabindex="-1">GitHub (changed since Course A&#39;s check) <a class="header-anchor" href="#github-changed-since-course-as-check" aria-label="Permalink to &quot;GitHub (changed since Course A&#39;s check)&quot;">​</a></h3><ul><li><strong>Actions</strong> moved to a dollar-denominated, shared compute entitlement, announced with the 28 Oct cloud rollout. The entitlement covers standard runners and Copilot cloud sandboxes. <ul><li><strong>Allowances:</strong> GitHub Free gets <strong>$12/month</strong>; <strong>Pro (students) $18</strong>.</li><li><strong>Rates:</strong> Linux 2-core $0.006/min, Windows $0.010/min, macOS $0.062/min.</li><li><strong>Free usage:</strong> standard runners are <strong>free in public repos</strong> and don&#39;t reduce the allowance. <strong>Self-hosted runners are free.</strong></li><li><strong>Larger runners</strong> are billed even for public repos.</li><li><a href="https://docs.github.com/en/billing/concepts/product-billing/github-actions" target="_blank" rel="noreferrer">Actions billing</a> [official].</li></ul></li><li><strong>Codespaces:</strong> Free gets 120 core-hours (about 60 h on 2 cores) and 15 GB. Pro gets 180 (about 90 h) and 20 GB. Usage is blocked, not billed, when no payment method is set [A]. <a href="https://docs.github.com/en/billing/concepts/product-billing/github-codespaces" target="_blank" rel="noreferrer">Codespaces billing</a>.</li><li><strong>Pages:</strong> public repos on Free; public <strong>and private</strong> on Pro. Sites are public by default. <a href="https://docs.github.com/en/pages/getting-started-with-github-pages/github-pages-limits" target="_blank" rel="noreferrer">GitHub docs</a> [official, snippet].</li><li><strong>Code security on public repos at $0:</strong><ul><li>Free on public repos: CodeQL code scanning, <strong>Copilot Autofix</strong>, secret scanning, push protection and Dependabot updates.</li><li>Private repos need Code Security (<strong>$30/active committer/month</strong>) or Secret Protection ($19).</li><li>New public previews (28 Oct): &quot;AI Scan&quot; for languages CodeQL doesn&#39;t support, and code scanning for AI apps.</li><li><a href="https://github.com/security/plans" target="_blank" rel="noreferrer">github.com/security/plans</a> [official]; codeql-bundle v2.27.4 (2 Nov) [GH].</li></ul></li></ul><h3 id="static-analysis" tabindex="-1">Static analysis <a class="header-anchor" href="#static-analysis" aria-label="Permalink to &quot;Static analysis&quot;">​</a></h3><ul><li><strong>Semgrep Community Edition:</strong> the engine is LGPL-2.1 (v1.183.0, 29 Oct). The <strong>Semgrep-maintained rules are under the Semgrep Rules License</strong> (internal, non-SaaS use only), and cross-file taint analysis is paid-only. <ul><li>Semgrep&#39;s platform has a &quot;Free Edition&quot;: <strong>10 contributors, 10 repos</strong>, Code and Supply Chain, 60 AI credits; secrets scanning needs Teams.</li><li><a href="https://semgrep.dev/pricing" target="_blank" rel="noreferrer">Semgrep pricing</a> [official]; <a href="https://docs.semgrep.dev/faq/comparisons/opengrep-1" target="_blank" rel="noreferrer">licensing comparison</a> [official, snippet].</li></ul></li><li><strong>Opengrep</strong> (an LGPL fork of Semgrep CE): v1.33.1, 29 Oct 2026 [GH].</li><li><strong>Ruff:</strong> 0.17.3 (27 Oct) [GH]. ESLint was not re-checked (no price involved).</li></ul><h3 id="testing-tools-all-free-and-open-source-gh" tabindex="-1">Testing tools (all free and open source, [GH]) <a class="header-anchor" href="#testing-tools-all-free-and-open-source-gh" aria-label="Permalink to &quot;Testing tools (all free and open source, [GH])&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tool</th><th>Release</th><th>Licence</th></tr></thead><tbody><tr><td>StrykerJS (JavaScript mutation testing)</td><td>v10.1.1 (23 Oct)</td><td>Apache-2.0; <strong>Node ≥22</strong></td></tr><tr><td>mutmut (Python mutation testing)</td><td>3.8.1 (28 Oct)</td><td>BSD-3; Python ≥3.10</td></tr><tr><td>PIT (Java mutation testing)</td><td>1.30.1 (14 Oct)</td><td>Apache-2.0</td></tr><tr><td>Cosmic Ray (Python mutation testing)</td><td>8.7.0 (9 Aug)</td><td>Slower cadence</td></tr><tr><td>Hypothesis (Python property-based testing)</td><td>6.170.14 (30 Oct)</td><td>Python ≥3.11</td></tr><tr><td>fast-check (JavaScript property-based testing)</td><td>4.10.2 (19 Sep)</td><td>MIT</td></tr></tbody></table><h3 id="llm-evals-and-tracing-gh-unless-noted" tabindex="-1">LLM evals and tracing ([GH] unless noted) <a class="header-anchor" href="#llm-evals-and-tracing-gh-unless-noted" aria-label="Permalink to &quot;LLM evals and tracing ([GH] unless noted)&quot;">​</a></h3><ul><li><strong>promptfoo:</strong> MIT, 0.125.1 (25 Oct), <strong>Node ≥22.22</strong>. <ul><li><strong>OpenAI announced its acquisition on 9 Mar 2026.</strong> The project says it stays MIT and will be folded into OpenAI&#39;s Frontier platform. <a href="https://gigazine.net/gsc_news/en/20260310-openai-to-acquire-promptfoo" target="_blank" rel="noreferrer">Gigazine</a> [3rd]; <a href="https://openai.com/zh-Hans-CN/index/openai-to-acquire-promptfoo/" target="_blank" rel="noreferrer">OpenAI</a> [official, snippet].</li></ul></li><li><strong>Inspect AI</strong> (UK AISI): MIT, 0.3.287 (31 Oct), Python ≥3.11. Good for agent evals in sandboxes.</li><li><strong>DeepEval:</strong> Apache-2.0, 4.3.2 on PyPI (27 Oct).</li><li><strong>OpenAI Evals</strong> repo: last push 14 Apr 2026, no releases. <strong>Treat it as dormant.</strong></li><li><strong>Langfuse:</strong> MIT core plus <code>ee/</code> directories. <strong>Owned by ClickHouse since Jan 2026.</strong> Self-hosting is free. The Cloud Hobby plan gives 50K units/month, 2 users and 30 days of data. <a href="https://langfuse.com/pricing" target="_blank" rel="noreferrer">langfuse.com/pricing</a>, <a href="https://langfuse.com/blog/joining-clickhouse" target="_blank" rel="noreferrer">announcement</a> [official].</li><li><strong>Arize Phoenix:</strong> <strong>Elastic License 2.0</strong> (source-available, fine for coursework); v21.0.0. The hosted AX Free tier gives 25K spans/month, 1 GB, 15-day retention and unlimited users. <a href="https://arize.com/pricing/" target="_blank" rel="noreferrer">arize.com/pricing</a> [official].</li></ul><h3 id="sandboxing-agents" tabindex="-1">Sandboxing agents <a class="header-anchor" href="#sandboxing-agents" aria-label="Permalink to &quot;Sandboxing agents&quot;">​</a></h3><ul><li><strong>Copilot local sandboxing</strong> went generally available on 7 Oct 2026 at no extra cost. <ul><li>It is <strong>off by default</strong>; turn it on with <code>/sandbox enable</code>.</li><li>Requirements: macOS 15+; on Linux, <code>bwrap</code> ≥0.5.0; on Windows, a recent Windows 11 build.</li><li><a href="https://github.blog/changelog/2026-10-07-local-sandboxing-for-github-copilot-now-generally-available" target="_blank" rel="noreferrer">Changelog</a> [official, snippet].</li></ul></li><li><strong>Docker Sandboxes</strong> (the <code>sbx</code> CLI) runs each agent in its own microVM; local use is free. <a href="https://docs.docker.com/ai/sandboxes/" target="_blank" rel="noreferrer">Docker docs</a>.</li><li><strong>Docker Desktop</strong> is free for educational use. <a href="https://docs.docker.com/subscription/desktop-license/" target="_blank" rel="noreferrer">Docker licence</a>.</li><li><strong>gVisor:</strong> release-20261102.0 [GH].</li></ul><hr><h2 id="5-mcp-in-late-2026" tabindex="-1">5. MCP in late 2026 <a class="header-anchor" href="#5-mcp-in-late-2026" aria-label="Permalink to &quot;5. MCP in late 2026&quot;">​</a></h2><ul><li><strong>Spec status:</strong> the current version is <strong>2026-07-28</strong>. It has a stateless core: no <code>initialize</code> handshake, an optional <code>server/discover</code>, and the version carried in every request&#39;s <code>_meta</code> or in the <code>MCP-Protocol-Version</code> header. <ul><li>Deprecated features stay at least 12 months (90 days under the expedited-removal exception).</li><li>The <strong>roadmap (updated 22 Aug 2026)</strong> gives <strong>no date for the next version</strong>. Its priorities are agentic messaging (Tasks and events), HTTP over stdio, agent identity (DPoP, workload identity), a redesigned <code>tools/call</code> result shape, and progressive discovery.</li><li><strong>Inference:</strong> expect a <code>tools/call</code> change within a year. Avoid grading on the exact <code>content</code>/<code>structuredContent</code> shape.</li><li><a href="https://modelcontextprotocol.io/specification/versioning" target="_blank" rel="noreferrer">Versioning</a>; <a href="https://modelcontextprotocol.io/development/roadmap" target="_blank" rel="noreferrer">roadmap</a> [official].</li></ul></li><li><strong>SDKs:</strong><ul><li>Tier 1: TypeScript, Python, C#, Go, Rust and <strong>Ruby</strong> (Ruby promoted 30 Oct 2026). Java is Tier 2; Swift, PHP and Kotlin are Tier 3. <a href="https://modelcontextprotocol.io/docs/sdk" target="_blank" rel="noreferrer">SDK list</a>, <a href="https://blog.modelcontextprotocol.io/" target="_blank" rel="noreferrer">MCP blog</a> [official].</li><li><strong>TypeScript v2</strong> (the stable line since 27 Jul 2026, for spec 2026-07-28) is split into <code>@modelcontextprotocol/server</code> and <code>@modelcontextprotocol/client</code> (v2.4.0, Node ≥20). Schemas use Standard Schema (Zod v4 and others). The old <code>@modelcontextprotocol/sdk</code> (v1.32.2) gets security fixes &quot;for at least six months after the v2 release&quot;, so <strong>at least until late January 2027</strong>. <strong>Any 2025 tutorial that imports <code>@modelcontextprotocol/sdk/server/mcp.js</code> is on the legacy line.</strong> <a href="https://github.com/modelcontextprotocol/typescript-sdk" target="_blank" rel="noreferrer">TS SDK README</a> [GH].</li><li><strong>Python v2</strong> (<code>mcp</code> 2.3.0, <strong>Python ≥3.11</strong>) uses <code>from mcp.server import MCPServer</code> and runs with <code>uv run mcp dev server.py</code>. The FastMCP-era imports in older tutorials are outdated. <a href="https://github.com/modelcontextprotocol/python-sdk" target="_blank" rel="noreferrer">Python SDK README</a> [GH].</li></ul></li><li><strong>Building and testing a server at $0:</strong><ol><li>Write a 15-line server with the Python or TypeScript SDK.</li><li>Exercise it in <strong>MCP Inspector</strong> (2.13.0, Node ≥22.19), via <code>mcp dev</code> or <code>npx @modelcontextprotocol/inspector</code>.</li><li>Unit-test it with the SDK&#39;s own <code>Client</code>, which can launch a stdio subprocess.</li><li>Connect it to the student&#39;s own agent (Gemini or Groq key, or Ollama), to Copilot in VS Code (MCP included on Free and Student), and to Gemini CLI or OpenCode.</li><li>For remote HTTP servers, run them locally first; hosting is in TOOLS.md.</li></ol></li><li><strong>Security issues to teach:</strong><ul><li><strong>The spec&#39;s own attack catalogue</strong> (<a href="https://modelcontextprotocol.io/specification/2026-07-28/basic/security_best_practices" target="_blank" rel="noreferrer">Security Best Practices, 2026-07-28</a>): confused deputy; token passthrough (forbidden); SSRF during OAuth discovery, including cloud metadata at 169.254.169.254; state-handle hijacking; <strong>local MCP server compromise</strong> (malicious startup commands, DNS rebinding of localhost servers); <code>javascript:</code> or shell injection through authorization URLs; stdio proxy escalation; mix-up attacks; localhost redirect impersonation; and scope minimisation.</li><li><strong>Incidents in Course A&#39;s notes</strong> [A]: agents launching MCP servers declared in untrusted repo configs (GHSA-m84r-3mrm-j4p8); an OAuth credential leak in the TypeScript SDK (GHSA-6qxp-vccf-f47h); a fake &quot;MCP security audit&quot; npm package that registered an attacker&#39;s server; up to 15 lookalike servers per verified server (UpGuard). The advisory pages were <strong>not opened</strong>; verify them before using them on slides.</li></ul></li></ul><hr><h2 id="6-risks-for-a-0-design-what-broke-in-202526-and-fallbacks" tabindex="-1">6. Risks for a $0 design: what broke in 2025–26, and fallbacks <a class="header-anchor" href="#6-risks-for-a-0-design-what-broke-in-202526-and-fallbacks" aria-label="Permalink to &quot;6. Risks for a $0 design: what broke in 2025–26, and fallbacks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What happened</th><th>Effect on a course</th><th>Fallback</th></tr></thead><tbody><tr><td>Copilot moved to token-based AI credits (1 Jun 2026). Students reported the 200-credit Student allowance gone &quot;after about 10 to 20 Agent Mode requests&quot;, or within hours. No GitHub staff answer in the thread</td><td>Agent mode can&#39;t be the main workhorse</td><td>Use Copilot for completions, Ask mode and occasional agent runs. Do heavy agent work on the Gemini key, Zed Student or local models. <a href="https://github.com/orgs/community/discussions/197557" target="_blank" rel="noreferrer">#197557</a></td></tr><tr><td>Copilot new sign-ups (including Student) <strong>paused 20 Apr 2026</strong>; reopened gradually from 17 Jun</td><td>Students unverified at the start of term can be stuck</td><td>Verify in week 0. Copilot Free stays open. <a href="https://theregister.com/2026/04/20/microsofts_github_grounds_copilot_account" target="_blank" rel="noreferrer">The Register</a> [3rd]; <a href="https://www.layer3labs.io/guides/github-copilot-student" target="_blank" rel="noreferrer">Layer3Labs</a> [3rd]</td></tr><tr><td>Gemini CLI free login ended (18 Jun); Gemini Code Assist GitHub review app shut down (17 Jul); <strong>GitHub Models retired (30 Jul)</strong></td><td>Labs written in 2025 broke mid-year</td><td>An API-key path, plus provider-swappable code (<code>LLM_BASE_URL</code>, <code>LLM_API_KEY</code>, <code>LLM_MODEL</code>)</td></tr><tr><td>Amazon Q Developer Free closed to new accounts (15 May 2026); Kiro&#39;s student offer limited to listed schools (UIdaho absent)</td><td>No AWS path at $0 for UIdaho</td><td>Use something else, or ask AWS to add UIdaho</td></tr><tr><td>Antigravity Free loses Claude 4.6 and GPT-OSS-120b on <strong>2 Nov 2026</strong></td><td>&quot;Free frontier models&quot; in the IDE are gone</td><td>Gemini 3.8 Flash in Antigravity, or Zed Student</td></tr><tr><td>CMU 15-113: &quot;Free-tier credits on Copilot, Claude, Gemini, and Render all ran out mid-assignment&quot;; Kiro &quot;uses a lot of credits&quot; [A]</td><td>Assignments stall</td><td>Planned tool rotation, plus a credits budget per week</td></tr><tr><td>OpenCode Console breach and supply-chain attacks on AI configs and keys (Oct 2026) [A]</td><td>Stolen keys and bills</td><td>Use free-tier keys with no billing attached, store them only in environment variables, rotate them each term, set spending caps</td></tr><tr><td>Open-source maintainers throttling AI-generated PRs. GitHub lets repos cap open PRs from users without write access (17 Jun 2026) and exempt contributors by account age or history (28 Oct). The MCP TypeScript SDK itself allows &quot;one open pull request at a time&quot; from such contributors</td><td><strong>Team-project risk</strong>: new student accounts may be capped, or their PRs closed unread</td><td>Choose upstream projects in week 1 with maintainer buy-in. Read <code>CONTRIBUTING.md</code> and the project&#39;s AI policy. Disclose AI use. Keep PRs small. <a href="https://gigazine.net/gsc_news/en/20260618-github-limit-pull-request" target="_blank" rel="noreferrer">Gigazine</a> [3rd]; <a href="https://github.blog/changelog/month/10-2026/page/2/" target="_blank" rel="noreferrer">Oct changelog page 2</a> [official]</td></tr><tr><td>Ollama Cloud&#39;s free starter credits apparently removed (Sept → Nov)</td><td>No free hosted big-model fallback</td><td>A lab GPU, or Zen free models with zero retention</td></tr></tbody></table><p><strong>Free-tier data use, summarised:</strong></p><ul><li><strong>Used for training or improvement by default:</strong> Gemini API free tier (no opt-out), Copilot individual plans (opt-out), several Zen free models, and Mistral (opt-out).</li><li><strong>Not used:</strong> Groq and Ollama Cloud don&#39;t retain or train.</li><li><strong>Inference:</strong> public open-source code is low-risk to send. Personal data, grades, unreleased research code and secrets must never go to the free tiers that train.</li></ul><hr><h2 id="recommended-0-stack-for-course-b" tabindex="-1">Recommended $0 stack for Course B <a class="header-anchor" href="#recommended-0-stack-for-course-b" aria-label="Permalink to &quot;Recommended $0 stack for Course B&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Layer</th><th>Primary ($0)</th><th>Fallback 1</th><th>Fallback 2</th><th>Notes</th></tr></thead><tbody><tr><td><strong>Chat</strong></td><td>Claude Free (Sonnet 5.5; 18+) [A]</td><td>ChatGPT Free (GPT-6 Luna; unlimited text) [A]</td><td>Microsoft Copilot with a UIdaho login (UIdaho support article &quot;How to access Microsoft Copilot&quot; seen only as a title; <strong>check data protections with ITS</strong>)</td><td>Turn off training in each tool</td></tr><tr><td><strong>IDE agent</strong></td><td>VS Code + <strong>Copilot Student</strong> in Codespaces (completions, Ask, short agent runs)</td><td><strong>Zed Student</strong> ($10/month of hosted tokens for 1 year; MCP; ACP external agents)</td><td>Cline or Kilo Code + Gemini key or the lab Ollama server</td><td>Antigravity Free (Gemini 3.8 Flash) is an extra option</td></tr><tr><td><strong>CLI agent</strong></td><td><strong>Gemini CLI + free AI Studio key</strong> (250 requests/day, Flash)</td><td>Copilot CLI (Student credits; <code>/model</code> for local Ollama)</td><td>OpenCode + lab Ollama (64K context) or zero-retention Zen free models</td><td>Department-funded: Claude Code or Codex. <strong>Codex student credits ($100) are worth testing in week 0</strong></td></tr><tr><td><strong>Cloud / background / parallel agents</strong></td><td><strong>Jules</strong> (15 tasks/day, 3 concurrent)</td><td>Copilot cloud agent on students&#39; forks (confirm Student counts as &quot;paid&quot; after 28 Oct; 59-minute limit)</td><td>Headless CLI agents in GitHub Actions on public forks (Agentic Workflows with the Gemini engine, <code>max-ai-credits</code> capped), or several local agents in git worktrees</td><td>OpenHands on the lab GPU for a self-hosted demo</td></tr><tr><td><strong>AI code review</strong></td><td><strong>CodeRabbit</strong>, free &quot;forever for public repositories&quot; (on students&#39; public forks; data terms not checked)</td><td><strong>PR-Agent</strong> (MIT, v0.49.0, 25 Oct) as an Action with a Gemini key</td><td>Copilot code review, <strong>Lite effort only</strong> (about $0.25 each; Balanced about $1.50)</td><td>Don&#39;t plan more than 1–2 Copilot reviews per student per month</td></tr><tr><td><strong>LLM API for student-built agents</strong></td><td><strong>Gemini API</strong> (<code>gemini-3.5-flash-lite</code> / <code>gemini-3.8-flash</code>, OpenAI-compatible)</td><td><strong>Groq</strong> (gpt-oss-120b; keep each request under 8K tokens)</td><td>Lab Ollama endpoint; OpenRouter <code>:free</code> (50/day)</td><td>Optional department step: a one-time $10 OpenRouter credit per student gives 1,000/day</td></tr><tr><td><strong>Local model</strong></td><td><strong>Lab GPU</strong> (24–32 GB): <code>gpt-oss:20b</code> or <code>qwen3.8:27b</code> at 64K context, served to teams</td><td><code>devstral-small-2:24b</code> / <code>qwen3-coder:30b</code> (same GPU)</td><td>16 GB laptops: <code>gemma4:e4b</code>/<code>12b</code> (small-agent and MCP labs only)</td><td>Bench all of them in week 0 with the course&#39;s tool-calling smoke test</td></tr><tr><td><strong>CI</strong></td><td>GitHub Actions on <strong>public</strong> repos (standard runners free)</td><td>Students&#39; private repos: $18/month entitlement (about 3,000 Linux minutes)</td><td>Self-hosted runner on a lab machine (free), <strong>for trusted repos only, never public fork PRs</strong></td><td>—</td></tr><tr><td><strong>Static analysis</strong></td><td>CodeQL default setup + Copilot Autofix (free on public repos)</td><td>Semgrep CE / Opengrep (LGPL; note the rules licence)</td><td>Ruff / ESLint</td><td>Semgrep Free Edition: 10 contributors, 10 repos</td></tr><tr><td><strong>Testing tools</strong></td><td>Hypothesis / fast-check (property-based)</td><td>StrykerJS / mutmut / PIT (mutation)</td><td>Cosmic Ray (Python)</td><td>Standardise on Node 22.22+ and Python 3.12 (promptfoo, Stryker, Inspector, MCP v2 and Hypothesis all need them)</td></tr><tr><td><strong>Evals</strong></td><td><strong>promptfoo</strong> (MIT; OpenAI-owned)</td><td><strong>Inspect AI</strong> (MIT; agent evals)</td><td>DeepEval (Apache-2.0)</td><td>Tracing: Langfuse self-hosted (MIT core) → Phoenix (ELv2) → Langfuse Cloud Hobby (50K units/month)</td></tr><tr><td><strong>Sandbox</strong> (extra)</td><td>Codespaces</td><td>Dev containers + Docker Desktop (free for education) / Docker Sandboxes</td><td>Copilot <code>/sandbox enable</code>, gVisor on lab Linux</td><td>Never open a received folder with an agent before checking <code>.git/config</code> [A]</td></tr></tbody></table><p><strong>The biggest risks, ranked:</strong></p><ol><li>Copilot Student&#39;s roughly $2/month credit pool and $1.50 average code reviews.</li><li>The Gemini free tier&#39;s unpublished, changeable limits and training on data, while it carries most of the heavy agent load.</li><li>Copilot &quot;paid plans only&quot; cloud features (from 28 Oct), whose status for Student is unknown.</li><li>Upstream projects throttling AI-assisted PRs.</li><li>Local models that are too weak for agentic work on large codebases.</li><li>Deadlines: the Google AI Pro offer must be redeemed by 31 Dec 2026, Codex credits expire after 12 months, the Zed Student year runs out, and TypeScript MCP v1 support ends around late January 2027.</li></ol><h2 id="gaps-could-not-verify-on-2026-11-02" tabindex="-1">Gaps (could not verify on 2026-11-02) <a class="header-anchor" href="#gaps-could-not-verify-on-2026-11-02" aria-label="Permalink to &quot;Gaps (could not verify on 2026-11-02)&quot;">​</a></h2><ul><li><strong>Copilot:</strong> the official size of the Student credit allowance; whether Student counts as a &quot;paid plan&quot; for the 28 Oct cloud features; whether local or Fusion local routing consumes credits.</li><li><strong>Antigravity:</strong> whether the 2 Nov model removal took effect; whether the Google student AI Pro year counts as a trial.</li><li><strong>Codex student credits:</strong> whether they work on a Free account with usable models (claim page returned 403).</li><li><strong>Free-tier limits:</strong> Groq&#39;s Free-tab figures were not shown to the fetch tool; Mistral&#39;s free limits are third-party only.</li><li><strong>CodeRabbit:</strong> data and training terms; whether the open-source offer is limited.</li><li><strong>Devin Desktop:</strong> official pricing (page unreachable).</li><li><strong>UIdaho:</strong> what Microsoft Copilot data protection students get (support page TLS error).</li><li><strong>CVE details:</strong> taken from Course A notes; not re-opened.</li></ul>',54)])])}const p=t(a,[["render",s]]);export{h as __pageData,p as default};
